import type { Announcement } from "../types";
import { DEMO_ISSUES } from "../data/places";
import { ANN_CAT, ISSUE_CAT, STATUS, fmtDate } from "../labels";
import { NO_INFO } from "./knowledge";

// Rule-based answers used when GEMINI_API_KEY is not set. Not generated by Gemini.
const has = (q: string, ...w: string[]) => w.some((x) => q.includes(x));

// Every answer is at most 2 sentences, like the Gemini answers: items are joined with ";" inside one sentence.
const MAX_ITEMS = 3;
const noEnd = (s: string) => s.trim().replace(/[.!?…]+$/, "");

function annShort(a: Announcement) {
  const where = [a.location.bag, a.location.area].filter(Boolean).join(", ") || a.location.sum;
  const when = a.start ? `${fmtDate(a.start, true)}${a.end ? "–" + fmtDate(a.end, true).slice(11) : ""}` : "цаг тодорхойгүй";
  return `${noEnd(a.title)} — ${where}, ${when}${a.verification === "demo" ? " (жишээ)" : ""}`;
}

/** One sentence listing up to MAX_ITEMS items, or NO_INFO when there are none. */
function listSentence(head: string, items: string[]): string {
  if (!items.length) return NO_INFO;
  const more = items.length > MAX_ITEMS ? `, болон өөр ${items.length - MAX_ITEMS}` : "";
  return `${head}: ${items.slice(0, MAX_ITEMS).join("; ")}${more}.`;
}

export function demoAnswer(question: string, anns: Announcement[], area?: string): string {
  const q = question.toLowerCase();
  const pick = (cat: Announcement["category"][]) => anns.filter((a) => cat.includes(a.category));

  if (has(q, "мэдээлэх", "яаж", "хэрхэн", "илгээх", "гомдол")) {
    return "«Асуудал мэдээлэх» хэсэгт гарчиг, ангилал, байршил, тайлбар (хүсвэл зураг) оруулаад «Илгээх» дарвал хяналтын дугаар (жишээ нь OR-…) гарах бөгөөд түүгээр явцаа шалгана. Мэдээлэл албан байгууллагад автоматаар илгээгдэхгүй тул яаралтай үед 101, 102, 103, 105 руу залгана уу.";
  }
  if (has(q, "шийдвэрлэгдсэн", "шийдсэн", "шийдэгдсэн")) {
    const done = DEMO_ISSUES.filter((i) => i.status === "resolved");
    return listSentence("Шийдвэрлэгдсэн асуудлууд (бүгд жишээ өгөгдөл)", done.map((i) => `${noEnd(i.title)} — ${i.area}${i.action ? ", " + noEnd(i.action) : ""} (${fmtDate(i.resolvedAt)})`));
  }
  if (has(q, "ойролцоо", "асуудал")) {
    const list = DEMO_ISSUES.filter((i) => i.status !== "resolved" && (!area || i.area === area));
    const use = list.length ? list : DEMO_ISSUES.filter((i) => i.status !== "resolved");
    const head = area && !list.length ? `«${area}»-д бүртгэгдсэн асуудал алга, хотын хэмжээнд (жишээ өгөгдөл)` : "Идэвхтэй асуудлууд (жишээ өгөгдөл)";
    return listSentence(head, use.map((i) => `${noEnd(i.title)} — ${i.area}, ${ISSUE_CAT[i.category]}, ${STATUS[i.status].label}`));
  }
  if (has(q, "ус", "дулаан")) {
    const list = pick(["water"]);
    const mine = area ? list.filter((a) => a.location.area === area) : [];
    const head = area && !mine.length ? `«${area}»-д хамаарах усны баталгаажсан зар олдсонгүй, хотын хэмжээнд` : "Усны мэдээлэл";
    return `${listSentence(head, (mine.length ? mine : list).map(annShort))}`;
  }
  if (has(q, "цахилгаан", "гэрэл тасрах")) return `${listSentence("Цахилгааны мэдээлэл", pick(["electricity"]).map(annShort))}`;
  if (has(q, "зам", "түгжрэл", "автобус", "тээвэр")) return `${listSentence("Зам, тээврийн мэдээлэл", pick(["road", "traffic", "transport"]).map(annShort))}`;
  if (has(q, "өнөөдөр", "мэдэгдэл", "шинэ", "зар")) {
    return `${listSentence("Сүүлийн мэдэгдлүүд", anns.map(annShort))}`;
  }
  for (const [k, v] of Object.entries(ANN_CAT)) if (q.includes(v.label.toLowerCase())) return listSentence(v.label, pick([k as Announcement["category"]]).map(annShort));
  return `${NO_INFO} Жишээ нь «Өнөөдөр ямар мэдэгдэл байна?», «Манай багт ус тасрах уу?», «Асуудал хэрхэн мэдээлэх вэ?» гэж асууж болно.`;
}
